"use strict";
/* Two direct services: support through review, and a small, recorded neighbor trial. */
(()=>{
 const d=()=>globalThis.RebirthCommunity.data()?.social;
 const root=()=>'/api/merchants/'+encodeURIComponent(state.merchant.merchant_id);
 const now=()=>{const x=new Date();return [x.getFullYear(),String(x.getMonth()+1).padStart(2,'0'),String(x.getDate()).padStart(2,'0')].join('-')};
 const status={waiting:'待约定协助',arranged:'已约好一件事',following:'待店主回访',paused:'暂时停一停',closed:'本轮已回访',withdrawn:'已撤回求助'};
 let focusId=null;
 const resultNames={helped:'我觉得有帮助',unchanged:'暂时没看出变化',unsuitable:'不适合本店',stopped:'已停止尝试'};
 const eventNames={plan:'2. 约好谁来、怎么做',visit:'3. 记这次实际做了什么',review:'4. 记最后解决了多少',pause:'暂停',resume:'重新跟进',withdraw:'撤回求助'};
 const btn=(label,action,id='',primary=false,extra='')=>`<button type="button" class="button ${primary?'primary':'secondary'}" data-social="${action}" data-id="${h(id)}" ${extra}>${h(label)}</button>`;
 const route=(label,path)=>`<button type="button" class="button secondary" data-app-route="${h(path)}">${h(label)}</button>`;
 const examples={problem:'例如：货架上的数量和进货单对不上，不知道该怎么核对。',goal:'例如：先把一种商品的数量核对清楚。写一件能做完的小事就行。',availability:'例如：周二下午2点到3点。这里只记时间，不会通知别人。',helper_alias:'例如：小王、家人，或我自己。这里只记称呼，不会替你联系。',step:'例如：拿一张进货单，一起核对一款商品的件数。',planned_minutes:'填预计需要的分钟数，例如15。不知道就先约一个能接受的时间。',actual_minutes:'填实际花的分钟数。例如做了10分钟就填10；没做填0。',extra_spend:'只填这次额外花的钱。例如买标签花2元就填2，没花钱填0。',blockers:'例如：采购单还没找齐；如果没有困难，就写“暂时没有”。',notes:'写实际发生的事和你怎么知道的。例如：当面一起数了20件，和进货单逐项核对。',merchant_voice:'例如：现在会核对一种商品了，但其他商品还没弄清楚。不必写好评。',next_choice:'例如：明天下午先找齐采购单，再核对第二种商品；不继续就写原因。',fit_note:'例如：我们店也有库存对不上的问题，但商品种类更少。照实际情况写。',adapted_step:'例如：今天只数清一种商品，再与进货单核对。不要一次安排太多事。',minutes_cap:'这次最多愿意花多少分钟？例如15。',spend_cap:'这次最多愿意多花多少钱？不打算花钱就填0。',stop_when:'例如：找不到进货单就先停下，等资料齐了再做。',actual:'例如：只数了货架，发现采购单不全，还没办法核对差额。没做就写“还没开始”。',source_note:'例如：今天的盘点纸单；如果只是本人回忆，就写“本人回忆，尚未核对”。',next_step:'例如：明天先找齐进货单，再决定是否继续。也可以写“先停止，原因是……”',planned_on:'选你准备做这件事的日期，不一定是今天。',next_on:'选准备再来看结果的日期。这里只记待办，不会发送手机通知。',observed_on:'选实际查看结果的日期。'};
 const hint=(name,example=examples[name])=>example?`<small class="social-field-help" id="social-help-${name}">${h(example)}</small>`:'';
 const field=(label,name,value='',type='text',extra='')=>`<label class="form-label">${h(label)}<input class="field" aria-label="${h(label)}" ${examples[name]?`aria-describedby="social-help-${name}"`:''} name="${name}" value="${h(value)}" type="${type}" ${extra}>${hint(name)}</label>`;
 const area=(label,name,value='',limit=1600,example=examples[name])=>`<label class="form-label">${h(label)}<textarea class="field" aria-label="${h(label)}" ${example?`aria-describedby="social-help-${name}"`:''} name="${name}" required maxlength="${limit}" placeholder="${h(example||'按实际情况填写，不知道的不要编造。')}">${h(value)}</textarea>${hint(name,example)}</label>`;
 const check=(label,name,required=true,value=false)=>`<label class="checkbox-line"><input type="checkbox" name="${name}" ${required?'required':''} ${value?'checked':''}>${h(label)}</label>`;
 const select=(label,name,items,value)=>`<label class="form-label">${h(label)}<select class="field" name="${name}">${Object.entries(items).map(([k,v])=>`<option value="${h(k)}" ${k===value?'selected':''}>${h(v)}</option>`).join('')}</select></label>`;
 const hidden=(name,value)=>`<input type="hidden" name="${name}" value="${h(value||'')}">`;
 const group=html=>`<div class="form-grid two">${html}</div>`;
 const empty=(title,note,action)=>`<div class="social-empty"><h4>${h(title)}</h4><p>${h(note)}</p>${action||''}</div>`;
 const intro=(eyebrow,title,note,action)=>`<div class="social-intro"><span class="comm-eyebrow">${h(eyebrow)}</span><h3>${h(title)}</h3><p>${h(note)}</p>${action||''}</div>`;
 const progress=c=>{const p=c.status==='closed'?3:c.visits.length?2:c.plan?1:0;return `<ol class="social-progress" aria-label="陪跑进度">${['说清困难','约好一件事','留下协助记录','问问店主'].map((s,i)=>`<li class="${i<=p?'reached':''}"><span>${i+1}</span>${s}</li>`).join('')}</ol>`};
 function support(){const s=d(),open=s.cases.filter(c=>!['closed','withdrawn'].includes(c.status)),closed=s.cases.filter(c=>['closed','withdrawn'].includes(c.status));return intro('有困难，不必一个人想办法','先帮上一件具体的小事。','不会用表格、盘点总差数、忙不过来？先说清一件事，再和已有的协助者约定。本机登记不会自动分配志愿者或发送消息。',btn('1. 记下我遇到的困难','request','',true))+`<div class="social-guide-line">说清困难 → 约好协助 → 记下实际行动 → 由店主回看</div><h4 class="social-section-heading">正在跟进 · ${open.length}件</h4>${open.map(supportCard).join('')||empty('这会儿没有待跟进的求助','遇到操作或经营资料困难时，从上方按钮开始。也可以由家人、同学或已有的社区协助者一起填写。')}<div class="social-related">${route('打印与交接','service/handover')}${route('记录30天变化','service/impact')}${route('看看邻店怎么做','service/learning')}${route('资源互助','service/mutual')}</div>${closed.length?`<h4 class="social-section-heading">以前的回访与撤回</h4>${closed.slice().reverse().map(supportCard).join('')}`:''}`}
 function supportCard(c){let actions='';
  if(c.status==='waiting')actions=btn('2. 约好谁来、怎么做','plan',c.id,true);
  if(c.status==='arranged')actions=btn('3. 记这次实际做了什么','visit',c.id,true)+btn('调整约定','plan',c.id);
  if(c.status==='following')actions=btn('4. 记最后解决了多少','review',c.id,true)+btn('再记一次协助','visit',c.id);
  if(['paused','closed'].includes(c.status))actions=btn(c.status==='paused'?'继续跟进':'重新跟进','resume',c.id,c.status==='paused');
  if(c.status==='closed')actions+=c.shared?route('查看整理的经验','service/learning'):btn('整理成邻店经验','share',c.id);
  if(['waiting','arranged','following'].includes(c.status))actions+=btn('暂时停一停','pause',c.id);
  return `<article class="social-case" id="social-record-${h(c.id)}" tabindex="-1"><div class="social-card-top"><span class="tag">${h(status[c.status])}</span><small>${h(d().categories[c.data.category])}</small></div><h4>${h(c.data.goal)}</h4><p>${h(c.data.problem)}</p>${progress(c)}<p class="social-next-explained">${h({waiting:'下一步：约好谁来、做哪一件事。保存记录不会自动通知别人。',arranged:'下一步：实际做过之后，记下做了什么、用了多久。还没做可以先离开，记录会保留。',following:'下一步：问问店主解决了多少，再写之后怎么办。没解决也照实记。',closed:'这一轮已经记完了。需要继续时点“重新跟进”。',paused:'这件事暂时暂停，准备继续时再点“继续跟进”。',withdrawn:'这条求助已撤回，旧记录仍保留。'}[c.status]||'')}</p>${c.next_on?`<p class="social-next-date ${c.next_on<=now()?'is-due':''}">${c.next_on<now()?'原安排已到期，请核对：':c.next_on===now()?'今天接着做：':'下次跟进：'}${h(c.next_on)}</p>`:''}${c.plan?`<div class="social-agreement"><strong>这次只做：${h(c.plan.data.step)}</strong><span>约定用时${c.plan.data.planned_minutes}分钟 · ${h(c.plan.data.helper_alias)}</span></div>`:''}${c.review?`<p>最近回访：${h(d().outcomes[c.review.data.outcome])}<br>店主反馈：${h(c.review.data.merchant_voice)}</p>`:''}<div class="social-card-actions">${actions}${btn('查看完整跟进记录','history',c.id)}</div></article>`;
 }
 function learning(){const s=d(),available=s.cards.filter(c=>!c.withdrawn&&!c.source_changed),ownUnavailable=s.cards.filter(c=>c.owned&&(c.withdrawn||c.source_changed));return intro('把一次陪伴，接到下一间店','方法可以借鉴，结果要自己验证。','这里只分享店主核对过的匿名方法；“没解决”也有价值。先看适用条件，再只挑一步安排尝试，之后留下真实结果。',btn('整理本店的一次经验','share','',true))+`<div class="social-related">${route('需要人一起梳理？去求助','service/support')}${route('记录本店30天变化','service/impact')}${btn('查看匿名使用记录','summary')}</div><h4 class="social-section-heading">我安排的试做 · ${s.adoptions.length}次</h4>${s.adoptions.slice().reverse().map(adoptionCard).join('')||empty('还没有安排借鉴','在下方找适合本店的一张经验卡，选择一个步骤。不会自动采购、发消息或修改原账。')}<h4 class="social-section-heading">本机邻店经验 · ${s.synthetic?'模拟案例区':'实际登记区'}</h4><label class="form-label social-filter">按小店类型查看<select id="social-industry-filter" class="field"><option value="all">全部小店</option>${Object.entries(s.industries).map(([k,v])=>`<option value="${h(k)}">${h(v)}</option>`).join('')}</select></label><div class="social-experience-list">${available.map(experienceCard).join('')||empty('经验从真实回访里慢慢积累','先完成一轮求助、协助与回访，再由店主决定是否整理成匿名方法。不会预填虚构的成功案例。')}</div><p id="social-filter-empty" class="comm-empty" hidden>这个类型还没有经验。可查看其他类型的适用条件，也可以先记录本店的困难。</p>${ownUnavailable.length?'<h4 class="social-section-heading">本店留存的旧卡</h4>'+ownUnavailable.map(experienceCard).join(''):''}`}
 function experienceCard(c){const x=c.data,pending=d().adoptions.find(a=>a.data.share_id===c.id&&!a.latest);return `<article class="social-experience" data-social-industry="${h(x.industry)}"><div class="social-card-top"><span class="tag">${h(d().industries[x.industry])} · ${c.owned?'本店整理':'邻店方法'}</span><small>${c.withdrawn?'已撤回':c.source_changed?'来源已继续跟进，暂不供借鉴':'仅本机目录'}</small></div><h4>${h(x.title)}</h4><p>${h(x.problem)}</p><ol class="social-method">${x.steps.map(t=>`<li>${h(t)}</li>`).join('')}</ol><div class="social-conditions"><p><strong>适合什么情况</strong>${h(x.fits)}</p><p><strong>遇到什么先暂停</strong>${h(x.stop_when)}</p></div><p><strong>原店回访：</strong>${h(d().outcomes[x.outcome])}（本机自报）<br>${h(x.lesson)}</p><div class="social-card-actions">${!c.owned&&!c.withdrawn&&!c.source_changed?(pending?btn('查看已安排的尝试','focus-adoption',pending.id,true):btn('选一个步骤，安排试做','adopt',c.id,true)):c.owned&&!c.withdrawn?btn('撤回这张经验卡','withdraw-card',c.id):''}</div></article>`}
 function adoptionCard(a){const r=a.latest?.data,x=a.data;return `<article class="social-case" id="social-record-${h(a.id)}" tabindex="-1"><div class="social-card-top"><span class="tag">${r?h(resultNames[r.result]):'待尝试后回看'}</span><small>${h(x.next_on)}</small></div><h4>${h(x.adapted_step)}</h4><p>借鉴自：${h(x.card_snapshot.title)}<br>本店适用原因：${h(x.fit_note)}<br>这次最多：${x.minutes_cap}分钟、${h(x.spend_cap)}元；这是自设边界，不是收益预测。<br>暂停条件：${h(x.stop_when)}</p>${a.source_unavailable?'<p class="note-box amber">原卡已撤回或来源继续跟进。这里只保留当时借鉴快照；执行前重新核对，不继续传播旧卡。</p>':''}${r?`<p>实际：${h(r.actual)}<br>依据与其他影响：${h(r.source_note)}<br>额外用时${r.actual_minutes}分钟、支出${h(r.extra_spend)}元${r.actual_minutes>x.minutes_cap||Number(r.extra_spend)>Number(x.spend_cap)?'（已超过原定边界，请先复盘）':''}<br>下一步：${h(r.next_step)}</p>`:''}<p class="social-next-explained">${r?'结果已保存。以后有新情况，可点“修改或补充结果”。':'安排已保存。先按计划去做；做过之后，点下面“记这次试做的结果”。'}</p><div class="social-card-actions">${btn(r?'修改或补充结果':'记这次试做的结果','result',a.id,true)}${r&&!a.source_unavailable?(['unsuitable','stopped'].includes(r.result)?route('先把困难说清楚','service/support'):btn('再安排一小步','adopt',x.share_id)):''}${btn('打印这次安排','print-adoption',a.id)}${btn('查看结果历史','adoption-history',a.id)}</div></article>`}
 function render(tab){return tab==='support'?support():learning()}
 function surface(html,kind){globalThis.RebirthCommunity.surface(html,kind)}
 function form(kind,body,label='保存这份记录'){surface(`<form class="comm-form social-form" data-social-form="${kind}"><p class="social-fill-guide">${h({request:'第1步：记下困难。保存后，在这条记录上约好谁来一起做。',adopt:'先安排，不是记结果。写好怎么做、哪天做，再点底部“保存这次安排”。',result:'现在记实际结果。每个框下面都有例子；没有改善也可以保存。',event:body.includes('name="outcome"')?'第4步：记最后结果。选解决了多少，再写下一步。':body.includes('name="actual_minutes"')?'第3步：记实际做了什么。保存后，再填写最后结果。':'第2步：约好怎么做。保存后，做过了再记实际情况。'}[kind]||'按实际情况填写。填完点底部保存，保存成功后会回到这条记录。')}</p>${body}<p class="form-error" role="alert" hidden></p><div class="comm-form-actions"><button type="button" class="button secondary" data-app-action="back">返回，不保存</button><button type="submit" class="button primary">${h(label)}</button></div></form>`,kind)}
 function requestForm(){form('request',`<h3>先说清一件需要帮助的事</h3><p class="note-box">这份记录只保存在本机。可以和已有的家人、同学或社区协助者一起填，不会自动找到或通知他们。</p>${select('这次最需要什么帮助','category',d().categories)}${area('现在卡在哪一步？','problem')}${area('这次想先做成什么？','goal')}${group(field('什么时候方便一起做？','availability','','text','required maxlength="160"')+field('这份困难记录的日期','requested_on',now(),'date','required')+field('哪天再来看看？','next_on',now(),'date','required'))}${check('同意在本机保存这次求助，未授权向外发送经营资料','local_consent')}${check('允许把这条记录去掉店名后计入使用数量（可不选）','aggregate_consent',false)}`,'保存困难，接着约人一起做')}
 function caseForm(action,id){const c=d().cases.find(c=>c.id===id);if(!c)throw Error('请返回重新读取求助记录');let body=`<h3>${h(eventNames[action])}</h3><p class="note-box">这次想做成：${h(c.data.goal)}。请和店主确认后再填写。</p>${hidden('request_id',id)}${hidden('expected_id',c.last_id)}${hidden('action',action)}${field('本次实际日期','occurred_on',now(),'date','required')}`;
  if(action==='plan'){body+=group(field('谁来一起做（称呼即可，也可填“我自己”）','helper_alias',c.plan?.data.helper_alias||'','text','required maxlength="80"')+field('最多约定多少分钟（1—240）','planned_minutes',c.plan?.data.planned_minutes||20,'number','required min="1" max="240" step="1"'))+area('这次只一起做一件什么事？','step',c.plan?.data.step||'')+field('下次一起核对的日期','next_on',c.next_on<now()?now():c.next_on||now(),'date','required')+select('可选：同时记录这30天的变化','impact_case_id',{'':'暂不关联',...Object.fromEntries(globalThis.RebirthCommunity.data().cases.map(x=>[x.id,x.data.goal+' · '+x.data.metric_label]))},c.plan?.data.impact_case_id||'')+`<p class="form-hint">第一次使用可以不选，不影响保存。</p>`}
  else if(action==='visit')body+=group(field('这次实际协助了多少分钟？','actual_minutes','','number','required min="0" max="1440" step="1"')+field('这次实际额外支出（元，无则填0）','extra_spend','','number','required min="0" step="0.01"'))+area('还有什么困难？没有也请写明','blockers')+field('哪天问问店主是否真的有用？','next_on',now(),'date','required');
  else if(action==='review')body+=select('现在解决了多少？','outcome',d().outcomes,'unresolved')+area('店主自己的看法（不要代写成功评价）','merchant_voice')+area('接下来怎么办？继续、换方法或停下来','next_choice');
  else if(['pause','resume'].includes(action))body+=field('下次重新核对的日期','next_on',now(),'date','required');
  body+=area(action==='review'?'回访依据是什么？（当面询问、记录等）':action==='visit'?'一起实际做了什么？依据是什么？':'说明约定、暂停或继续的原因','notes','',1600,action==='review'?'例如：今天当面问过店主，他已经能自己核对一种商品，但仍缺采购单。':action==='visit'?'例如：当面一起数了20件，再与进货单核对；找不到的单据另记下来。':'例如：已和小王约好周二下午一起核对一种商品；如果暂停，写清为什么暂停。')+check('已和店主核对本次内容，按实际情况记录','confirmed');form('event',body,action==='review'?'保存最后结果':'保存这一步')
 }
 function history(id){const c=d().cases.find(c=>c.id===id);surface(`<h3>这件事，是怎样一步步走过来的</h3><div class="social-case"><h4>${h(c.data.goal)}</h4><p>${h(c.data.problem)}<br>方便时段：${h(c.data.availability)}<br>最早记录：${h(c.data.requested_on)}</p></div><ol class="social-timeline">${c.history.map(e=>`<li><span>${h(e.data.occurred_on)}</span><h4>${h(eventNames[e.data.action])}</h4><p>${h(e.data.notes)}</p>${e.data.step?`<p>${h(e.data.helper_alias)}：${h(e.data.step)}，约${e.data.planned_minutes}分钟</p>`:''}${e.data.blockers?`<p>本次${e.data.actual_minutes}分钟，额外支出${h(e.data.extra_spend)}元。还卡在：${h(e.data.blockers)}</p>`:''}${e.data.merchant_voice?`<p>${h(d().outcomes[e.data.outcome])}。店主：${h(e.data.merchant_voice)}<br>下一步：${h(e.data.next_choice)}</p>`:''}</li>`).join('')||'<li><p>已保存困难，下一步约定怎么帮。</p></li>'}</ol><div class="social-related">${btn('打印陪跑约定单','print-support',id,true)}${c.plan?.data.impact_case_id?route('回看关联的成效档案','service/impact'):route('建立一个30天观察起点','service/impact')}${route('带走纸单或登记交接','service/handover')}${!['withdrawn','closed'].includes(c.status)?btn('撤回这次求助','withdraw-request',id):''}${btn('调整匿名统计授权','privacy',id)}</div><p class="form-hint">目前${c.aggregate_consent?'允许':'未允许'}纳入本机匿名数量汇总；只统计记录，不证明真实受益。</p>`,'support-history')}
 function privacyForm(id){const c=d().cases.find(c=>c.id===id);form('privacy',`<h3>由店主决定是否纳入统计</h3>${hidden('request_id',id)}${hidden('expected_id',c.privacy_id)}<p>不纳入统计也能继续使用求助与跟进；这里不会删除原记录，也不会公开经营资料。</p>${check('允许这件求助的去名数量纳入本机匿名统计','aggregate_consent',false,c.aggregate_consent)}${check('已核对本次设置','confirmed')}`,'保存统计设置')}
 function adoptionPrivacyForm(id){const a=d().adoptions.find(x=>x.id===id);form('adoption-privacy',`<h3>由店主决定借鉴记录是否纳入统计</h3>${hidden('adoption_id',id)}${hidden('expected_id',a.privacy_id)}<p>不纳入统计也能继续使用，不删除实际记录，不公开店名和经营内容。</p>${check('允许这次借鉴的去名数量纳入本机匿名统计','aggregate_consent',false,a.aggregate_consent)}${check('已核对本次设置','confirmed')}`,'保存统计设置')}
 function shareForm(id){const cases=d().cases.filter(c=>c.status==='closed'&&c.review&&!c.shared);if(!cases.length){surface(`<h3>每次回访，只整理一份有依据的经验。</h3><p>还没有可整理的新回访。已有经验保留在邻店目录；继续跟进困难并再次回访后，可以整理新版。没改善的教训同样可以分享。</p>${route('去找人一起解决困难','service/support')}`,'share-start');return}
  form('share',`<h3>留下方法，把身份与原账留在店里</h3><p class="note-box">这里只在本机邻店目录共享。不要写店名、人名、电话、详细地址、客户信息或原账金额；系统只带入回访结果标签，不会复制私有记录。</p>${select('这张经验来自哪次回访？','request_id',Object.fromEntries(cases.map(c=>[c.id,c.data.goal+' · '+d().outcomes[c.review.data.outcome]])),id)}${field('经验标题（简单说清做了什么）','title','','text','required maxlength="80"')}${select('适用的小店类型','industry',d().industries)}${area('适合解决什么问题？','problem','',800)}${area('步骤一（只写别人能照做的动作）','step1','',600)}<label class="form-label">步骤二（可留空）<textarea class="field" name="step2" maxlength="600"></textarea></label><label class="form-label">步骤三（可留空）<textarea class="field" name="step3" maxlength="600"></textarea></label>${area('具备什么条件才适合借鉴？','fits','',800)}${area('遇到什么情况先暂停、不要照做？','stop_when','',800)}${area('做完学到了什么？没解决的地方也请留下','lesson','',1200)}${check('已检查文字，只保留匿名方法；不含店名、身份和原账细节','anonymous_checked')}${check('同意这张方法卡出现在本机邻店目录，可随时撤回','share_consent')}`,'保存匿名经验卡')}
 function adoptForm(id){const c=d().cards.find(c=>c.id===id);if(!c)throw Error('原卡已变化，请返回重新查看');const x=c.data;form('adopt',`<h3>只借鉴一步，按本店条件改一改</h3><p class="note-box">${h(x.title)}<br>适用条件：${h(x.fits)}<br>原店回访：${h(d().outcomes[x.outcome])}。经验不是效果承诺。</p>${hidden('share_id',id)}${select('这次只选哪个步骤？','step_index',Object.fromEntries(x.steps.map((v,i)=>[i,v])))}${area('为什么适合本店？有哪些不同？','fit_note')}${area('这次准备怎么做？','adapted_step')}${group(field('准备哪天做？','planned_on',now(),'date','required')+field('哪天再来看结果？','next_on',now(),'date','required')+field('最多花多少分钟？','minutes_cap',15,'number','required min="1" max="240" step="1"')+field('最多新增支出多少元？','spend_cap','0','number','required min="0" step="0.01"'))}${area('遇到什么情况就先不做？','stop_when',x.stop_when)}${check('允许把这次试做去掉店名后计入使用数量（可不选）','aggregate_consent',false)}${check('已核对适用条件，只登记小范围尝试；由店主决定是否执行','confirmed')}`,'保存这次安排')}
 function resultForm(id){const a=d().adoptions.find(a=>a.id===id),r=a.latest?.data;form('result',`<h3>有没有帮助，都如实留下。</h3><p class="note-box">本店安排：${h(a.data.adapted_step)}<br>原定最多${a.data.minutes_cap}分钟、${h(a.data.spend_cap)}元；实际超出也请照实填写，不用改写原安排。</p>${hidden('adoption_id',id)}${hidden('expected_id',a.latest?.id)}${select('试过之后，觉得怎么样？','result',resultNames,r?.result||'unchanged')}${group(field('实际观察日期','observed_on',now(),'date','required')+field('这件事一共多花了几分钟？','actual_minutes',r?.actual_minutes??'','number','required min="0" step="1"')+field('这件事一共多花了多少钱？','extra_spend',r?.extra_spend??'','number','required min="0" step="0.01"'))}${area('实际做了什么？结果是什么？','actual',r?.actual||'')}${area('这些情况是怎么确认的？还有别的原因吗？','source_note',r?.source_note||'')}${area('接下来打算怎么做？','next_step',r?.next_step||'')}${check('我已按实际情况填写，知道个人感受不等于一定能赚钱','confirmed')}`,'保存这次结果')}
 function withdrawForm(id){form('withdraw',`<h3>撤回这张匿名经验卡</h3>${hidden('share_id',id)}<p>撤回后，邻店不能再从目录打开或新建借鉴。此前已经保存的尝试仍保留历史与结果，以免丢失复盘依据。</p>${area('为什么撤回？','reason')}${check('确认撤回这张经验卡','confirmed')}`,'撤回卡片，保留历史')}
 function summary(){const s=d().summary;surface(`<h3>把陪伴的过程，记录得清清楚楚。</h3><p class="note-box">${s.synthetic?'模拟案例统计，不能当作真实社会成果。':'本机自愿登记统计，尚无独立核验。'}</p><div class="social-counts"><div><strong>${s.participating_shops}</strong><span>自愿参与统计的店铺</span></div><div><strong>${s.reviewed_shops}</strong><span>有店主回访记录的店铺</span></div><div><strong>${s.observed_30day_shops}</strong><span>关联同口径30天观察的店铺</span></div></div><p>共${s.requested_cases}件求助，${s.reviewed_cases}件已有回访，${s.closed_cases}件当前结束本轮跟进。${s.unresolved_cases}件最近回访仍是部分解决、未解决或停止，同样保留。</p><h4>经验有没有接到下一间店？</h4><p>本统计分组中，${s.learning_shops}家店登记过借鉴，${s.learning_reviewed_shops}家留下了实际结果。记录借鉴不等于实际采用，反馈有帮助不等于已经增加收益。</p><h4>30天同口径观察（各指标分开看）</h4>${s.metrics.map(x=>`<p>${h(x.label)}（${h(x.unit)}）：${x.cases}个档案，数值下降${x.lower}个、不变${x.same}个、上升${x.higher}个。变化不自动代表改善，也不证明工具造成。</p>`).join('')||'<p>还没有满足关联、同口径且满30天的观察，不补造效果数字。</p>'}<p class="form-hint">${h(s.definition)}</p>${btn('下载匿名统计与口径','download-summary')}`,'social-summary')}
 function remindersHtml(includeTasks=true){const reminders=includeTasks?(d()?.reminders||[]):[];return `<section class="social-today"><div><span class="comm-eyebrow">有困难，也有接着往前走的人</span><h2>需要时，一起把这件事做完。</h2></div><div class="social-related">${route('找人一起解决困难','service/support')}${route('看看别家店的办法','service/learning')}</div>${reminders.slice(0,3).map(r=>`<button type="button" class="social-reminder" data-app-route="service/${r.kind==='support'?'support':'learning'}" data-social-focus="${h(r.id)}"><span><strong>${h(r.title)}</strong><small>${h(r.date)} · ${r.date<now()?'原安排已到期，请核对':r.date===now()?'今天记得回看':'待跟进'} · ${r.kind==='support'?'陪跑跟进':'邻店尝试'}</small></span><b aria-hidden="true">→</b></button>`).join('')}</section>`}
 document.addEventListener('submit',async e=>{const f=e.target.closest('[data-social-form]');if(!f)return;e.preventDefault();const submit=f.querySelector('[type=submit]'),error=f.querySelector('.form-error');submit.disabled=true;error.hidden=true;try{const fd=new FormData(f),p=Object.fromEntries(fd.entries()),kind=f.dataset.socialForm;for(const k of ['local_consent','aggregate_consent','confirmed','anonymous_checked','share_consent'])if(f.querySelector('[name="'+k+'"]'))p[k]=fd.has(k);for(const k of ['planned_minutes','actual_minutes','step_index','minutes_cap'])if(fd.has(k))p[k]=intText(fd.get(k));if(kind==='share'){p.steps=['step1','step2','step3'].map(k=>p[k]?.trim()).filter(Boolean);delete p.step1;delete p.step2;delete p.step3}const routes={request:'support-request',event:'support-event',privacy:'support-consent','adoption-privacy':'experience-consent',share:'experience-share',adopt:'experience-adopt',result:'experience-result',withdraw:'experience-withdraw'};const saved=await api(root()+'/'+routes[kind],p);focusId=kind==='request'||kind==='adopt'?saved.id:p.request_id||p.adoption_id||null;toast(kind==='adopt'?'安排已保存。做过后，点“记这次试做的结果”。':kind==='result'?'结果已保存，可以在这条记录里查看。':'已保存，请看这条记录下面的下一步。');if(kind==='share')await globalThis.RebirthCommunity.open('learning');else await globalThis.RebirthCommunity.refresh()}catch(err){error.textContent=err.message;error.hidden=false;error.scrollIntoView({block:'nearest'})}finally{submit.disabled=false}});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-social]');if(!b)return;try{const a=b.dataset.social,id=b.dataset.id;if(a==='print-support'){const c=d().cases.find(c=>c.id===id);return globalThis.RebirthCommunity.paper('大字陪跑约定单',`<h1>一件小事，一起做完。</h1><p>${c.data.synthetic?'模拟案例，不是真实受益证明':'店主本机记录，未经独立核验'}</p><h2>这次先做什么</h2><p>${h(c.data.goal)}</p><p>${c.plan?h(c.plan.data.step)+' · 原约定'+c.plan.data.planned_minutes+'分钟':'尚未约定协助，请先一起核对。'}</p><h2>下次什么时候看看</h2><p>${c.next_on?h(c.next_on):'本轮已结束，需继续时重新跟进。'} · ${h(status[c.status])}</p><h2>目前走到哪里</h2><p>已有${c.visits.length}条实际协助记录。${c.review?'最近回访：'+h(d().outcomes[c.review.data.outcome]):'尚未回访，不补写结果。'}</p><p class="paper-note">这张纸是保存时的快照，不会自动更新。不包含店名、联系方式和原账；自由文字交给别人前请店主再检查。不自动分配人员，不代为执行经营操作。</p><p>实际做了什么：________________________<br>还需要帮助的地方：____________________<br>下次一起核对的日期：__________________</p>`)}if(a==='print-adoption'){const x=d().adoptions.find(x=>x.id===id);return globalThis.RebirthCommunity.paper('大字小步尝试单',`<h1>这次，只试一小步。</h1><p>${x.data.synthetic?'模拟案例，不是真实受益证明':'店主本机记录'}</p><h2>怎么做</h2><p>${h(x.data.adapted_step)}</p><h2>先核对条件</h2><p>${h(x.data.fit_note)}</p><p>最多用时${x.data.minutes_cap}分钟；新增支出上限见店主原记录。</p><h2>遇到什么先停下</h2><p>${h(x.data.stop_when)}</p><h2>什么时候回看</h2><p>${h(x.data.next_on)}</p>${x.source_unavailable?'<p class="paper-note">原经验卡已变化或撤回，先重新核对再执行。</p>':''}<p>实际做了什么：________________________<br>结果与额外负担：______________________<br>下一步：______________________________</p><p class="paper-note">这是安排快照，不是效果承诺。按实际情况回到“看看别家店的办法”记录结果；纸单交给他人前请检查自由文字。</p>`)}if(a==='request')return requestForm();if(Object.hasOwn(eventNames,a))return caseForm(a,id);if(a==='withdraw-request')return caseForm('withdraw',id);if(a==='history')return history(id);if(a==='privacy')return privacyForm(id);if(a==='adoption-privacy')return adoptionPrivacyForm(id);if(a==='focus-adoption'){const el=document.getElementById('social-record-'+id);el?.scrollIntoView({block:'start'});el?.focus({preventScroll:true});return}if(a==='share')return shareForm(id);if(a==='adopt')return adoptForm(id);if(a==='result')return resultForm(id);if(a==='withdraw-card')return withdrawForm(id);if(a==='summary')return summary();if(a==='adoption-history'){const x=d().adoptions.find(x=>x.id===id);return surface('<h3>尝试结果与更正记录</h3>'+x.history.map(r=>`<article class="social-case"><h4>${h(r.data.observed_on)} · ${h(resultNames[r.data.result])}</h4><p>${h(r.data.actual)}<br>依据：${h(r.data.source_note)}<br>下一步：${h(r.data.next_step)}<br>累计额外用时${r.data.actual_minutes}分钟、支出${h(r.data.extra_spend)}元</p></article>`).join('')+(x.history.length?'':'<p>尚未记录实际结果。</p>')+btn('调整这次借鉴的匿名统计授权','adoption-privacy',id),'learning-history')}
 if(a==='download-summary'){const payload={as_of:now(),...d().summary},url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='小店共益匿名记录-'+now()+'.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}}catch(err){toast(err.message)}});
 document.addEventListener('change',e=>{if(e.target.id!=='social-industry-filter')return;const v=e.target.value;let visible=0;for(const card of document.querySelectorAll('.social-experience-list .social-experience')){card.hidden=v!=='all'&&card.dataset.socialIndustry!==v;if(!card.hidden)visible++}document.querySelector('#social-filter-empty').hidden=visible>0});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-social-focus]');if(b)focusId=b.dataset.socialFocus},true);
 globalThis.RebirthSocial={render,remindersHtml,actionRemindersHtml:()=>{const r=d()?.reminders||[];return r.length?'<section class="social-action-reminders"><h2>需要跟进与回看的事</h2>'+r.map(x=>`<button type="button" class="social-reminder" data-app-route="service/${x.kind==='support'?'support':'learning'}" data-social-focus="${h(x.id)}"><span><strong>${h(x.title)}</strong><small>${h(x.date)} · ${x.kind==='support'?'陪跑跟进':'邻店尝试'}${x.date<now()?' · 原安排已到期，请核对':''}</small></span><b aria-hidden="true">→</b></button>`).join('')+'</section>':''},focusNext:id=>{focusId=id},afterRender:()=>{if(focusId){const el=document.getElementById('social-record-'+focusId);focusId=null;if(el)requestAnimationFrame(()=>{el.scrollIntoView({block:'start'});el.focus({preventScroll:true})})}}};
})();
